\set ON_ERROR_STOP on
begin;
set local search_path = public, extensions;
select no_plan();
select has_table('public','ebay_order_observer_scans','Dauerhafte gefrorene eBay-Scanfenster');
select has_table('public','ebay_order_observations','Bestelldedupe bleibt ohne Review-Snapshot');
select has_function('public','ebay_order_observer_claim',array['boolean','uuid[]','uuid[]','text'],'Interner Konto-Claim');
select ok(to_regprocedure('public.ebay_order_observer_claim(boolean,uuid[],uuid[])') is null,'Alte umgebungslose Claim-Signatur ist entfernt');
select is((select count(*) from pg_policies where schemaname='public' and tablename in ('ebay_order_observations','ebay_order_observer_scans','web_push_connection_incidents')),12::bigint,'Alle deklarativen getrennten Service-Role-Policies sind migriert');
create function pg_temp.ident(p_kind integer,p_index integer default 1) returns uuid language sql immutable as $$select ('47200000-0000-4000-8000-'||lpad((p_kind*100+p_index)::text,12,'0'))::uuid;$$;
insert into auth.users(id,email) select pg_temp.ident(1,number),'push-source-'||number||'@example.test' from generate_series(1,3) number;
insert into auth.sessions(id,user_id,created_at,updated_at) select pg_temp.ident(2,number),pg_temp.ident(1,number),now(),now() from generate_series(1,3) number;
insert into public.workspaces(id,name) values(pg_temp.ident(3),'Sources');
insert into public.workspace_members(workspace_id,user_id,role) values(pg_temp.ident(3),pg_temp.ident(1,1),'owner'),(pg_temp.ident(3),pg_temp.ident(1,2),'member'),(pg_temp.ident(3),pg_temp.ident(1,3),'admin');
insert into public.platform_operators(user_id) values(pg_temp.ident(1,1)),(pg_temp.ident(1,2));
insert into public.marketplace_connections(id,workspace_id,display_name,status,external_account_id) values(pg_temp.ident(4),pg_temp.ident(3),'Vinted','connected','472');
insert into public.ebay_connections(id,workspace_id,user_id,environment,status,external_account_id,authorization_version) values(pg_temp.ident(5),pg_temp.ident(3),pg_temp.ident(1,2),'production','connected','seller472',1);
insert into public.ebay_credentials(id,encrypted_tokens) values(pg_temp.ident(5),'encrypted-fixture');
insert into public.web_push_generations(id,user_id,token_hash) select pg_temp.ident(6,number),pg_temp.ident(1,number),repeat(number::text,64) from generate_series(1,3) number;
insert into public.web_push_devices(id,user_id,session_id,installation_id,endpoint_fingerprint,endpoint,p256dh,auth,vapid_key_id) select pg_temp.ident(6,number),pg_temp.ident(1,number),pg_temp.ident(2,number),pg_temp.ident(7,number),'source-'||number,'https://fcm.googleapis.com/source-'||number,repeat('x',87),repeat('x',22),'v1' from generate_series(1,3) number;
insert into public.web_push_preferences(device_id,workspace_id,categories) select pg_temp.ident(6,number),pg_temp.ident(3),array['message','order','connection'] from generate_series(1,3) number;
select ok(public.web_push_can_deliver(pg_temp.ident(1,1),pg_temp.ident(3),'message',pg_temp.ident(4),pg_temp.ident(2,1)),'Vinted Operator und Owner darf empfangen');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,2),pg_temp.ident(3),'message',pg_temp.ident(4),pg_temp.ident(2,2)),'Operator ohne Administration bleibt ausgeschlossen');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,3),pg_temp.ident(3),'message',pg_temp.ident(4),pg_temp.ident(2,3)),'Admin ohne Operator bleibt ausgeschlossen');
select ok(public.web_push_can_deliver(pg_temp.ident(1,1),pg_temp.ident(3),'favorite',pg_temp.ident(4),pg_temp.ident(2,1)),'Favoriten nur fuer Operator mit Administration');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,2),pg_temp.ident(3),'favorite',pg_temp.ident(4),pg_temp.ident(2,2)),'Favoriten verweigern Operator ohne Administration');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,3),pg_temp.ident(3),'favorite',pg_temp.ident(4),pg_temp.ident(2,3)),'Favoriten verweigern Admin ohne Operator');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,1),pg_temp.ident(3),'favorite',pg_temp.ident(5),pg_temp.ident(2,1)),'Favoritenziel darf keine eBay-Verbindung sein');
select public.web_push_enqueue_event('favorite-disabled',pg_temp.ident(3),'favorite',pg_temp.ident(4),jsonb_build_object('kind','vinted_favorites','connectionId',pg_temp.ident(4)));
select is((select count(*) from public.web_push_deliveries d join public.web_push_events e on e.id=d.event_id where e.category='favorite'),0::bigint,'Vorhandene Registrierungen aktivieren Favorite nicht automatisch');
select ok(public.web_push_can_deliver(pg_temp.ident(1,2),pg_temp.ident(3),'order',pg_temp.ident(5),pg_temp.ident(2,2)),'Eigener eBay Account ohne Operatorrechte');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,1),pg_temp.ident(3),'order',pg_temp.ident(5),pg_temp.ident(2,1)),'Workspaceowner darf anderes eBay Konto nicht empfangen');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,2),pg_temp.ident(3),'order',pg_temp.ident(5),pg_temp.ident(2,1)),'Fremde Sitzungskennung wird verweigert');
insert into public.store_orders(id,workspace_id,order_number) values(pg_temp.ident(8),pg_temp.ident(3),'SOURCE-ORDER');
select is((select count(*) from public.web_push_deliveries d join public.web_push_events e on e.id=d.event_id where e.category='order'),3::bigint,'Neue Shopzeile erzeugt drei berechtigte Auftraege atomar');
update public.store_orders set status='paid' where id=pg_temp.ident(8);
select is((select count(*) from public.web_push_events where source_key like 'store-order:%'),1::bigint,'Shopstatuswechsel erzeugt keine neue Bestellung');
insert into public.marketplace_account_entries(id,workspace_id,connection_id,kind,external_id,body) values(pg_temp.ident(9),pg_temp.ident(3),pg_temp.ident(4),'conversation','701','{}');
create function pg_temp.message_batch(p_observed text,p_id text,p_at text,p_conversation text default '701') returns jsonb language sql as $$select jsonb_build_object('version',1,'observedAt',p_observed,'complete',true,'coveredConversationIds','[]'::jsonb,'events',jsonb_build_array(jsonb_build_object('externalId',p_id,'externalConversationId',p_conversation,'occurredAt',p_at,'direction','inbound','source','conversation_snapshot')));$$;
select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',pg_temp.message_batch('2026-09-30T12:00:00.000Z','message:1','2026-09-30T11:59:00.000Z'));
select is((select count(*) from public.web_push_events where category='message'),0::bigint,'Erster Nachrichtenbestand bleibt still');
select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',pg_temp.message_batch('2026-09-30T12:02:00.000Z','message:2','2026-09-30T12:01:00.000Z'));
select is((select count(*) from public.web_push_deliveries d join public.web_push_events e on e.id=d.event_id where e.category='message'),1::bigint,'Spaeterer Eingang erreicht ausschliesslich Vintedberechtigten');
select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',pg_temp.message_batch('2026-09-30T12:03:00.000Z','message:2','2026-09-30T12:01:00.000Z'));
select is((select count(*) from public.web_push_events where category='message'),1::bigint,'Wiederholter Import erzeugt keinen neuen Eingang');
select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',pg_temp.message_batch('2026-09-30T12:04:00.000Z','message:3','2026-09-30T12:03:00.000Z','702'));
select is((select count(*) from public.web_push_events where category='message'),1::bigint,'Ungelesenes unbekanntes Gespraech wartet auf Aufloesung');
insert into public.marketplace_account_entries(workspace_id,connection_id,kind,external_id,body) values(pg_temp.ident(3),pg_temp.ident(4),'conversation','702','{}');
select is((select count(*) from public.web_push_events where category='message'),2::bigint,'Spaetere Gespraechsaufloesung erzeugt belegte Meldung');
select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',pg_temp.message_batch('2026-09-30T12:05:00.000Z','message:4','2026-09-30T11:00:00.000Z'));
select is((select count(*) from public.web_push_events where category='message'),2::bigint,'Historischer Backfill bleibt still');
select throws_ok($$select public.marketplace_record_message_event_batch(pg_temp.ident(3),pg_temp.ident(4),'472',jsonb_set(pg_temp.message_batch('2026-09-30T12:06:00.000Z','message:5','2026-09-30T12:05:00.000Z'),'{events,0,direction}','"outbound"'))$$,'22023',null,'Eigene ausgehende Nachrichten sind keine Eingangsquelle');
insert into public.marketplace_sync_schedules(workspace_id,connection_id,enabled,activated_by) values(pg_temp.ident(3),pg_temp.ident(4),true,pg_temp.ident(1,1));
update public.marketplace_sync_schedules set paused_reason='needs_login',consecutive_failures=1 where connection_id=pg_temp.ident(4);
update public.marketplace_sync_schedules set consecutive_failures=2 where connection_id=pg_temp.ident(4);
select is((select count(*) from public.web_push_events where category='connection'),0::bigint,'Erste und zweite weiche Ablehnung bleiben still');
update public.marketplace_sync_schedules set consecutive_failures=3,enabled=false where connection_id=pg_temp.ident(4);
update public.marketplace_sync_schedules set consecutive_failures=4 where connection_id=pg_temp.ident(4);
select is((select count(*) from public.web_push_events where category='connection'),1::bigint,'Dritte bestaetigte Sperre genau eine Stoerungsfolge');
update public.marketplace_sync_schedules set paused_reason=null,consecutive_failures=0 where connection_id=pg_temp.ident(4);
select ok((select is_open from public.web_push_connection_incidents where provider='vinted'),'Nutzerpause beendet belegte Stoerung nicht');
update public.marketplace_sync_schedules set enabled=true,paused_reason=null,last_success_at=clock_timestamp() where connection_id=pg_temp.ident(4);
-- Erholung kann ebenfalls vom Nullzustand nach bewusster Pause bestaetigt werden.
select is((select count(*) from public.web_push_events where category='connection'),1::bigint,'Erholung sendet keine Meldung');
update public.marketplace_sync_schedules set enabled=false,paused_reason='challenge' where connection_id=pg_temp.ident(4);
select is((select count(*) from public.web_push_events where category='connection'),2::bigint,'Bestaetigte Erholung erlaubt spaetere neue Stoerung');
update public.ebay_connections set status='needs_login' where id=pg_temp.ident(5);
select is((select count(*) from public.web_push_deliveries d join public.web_push_events e on e.id=d.event_id where e.category='connection' and e.connection_id=pg_temp.ident(5)),1::bigint,'eBay Reauth erreicht konkreten Accountbesitzer');
update public.ebay_connections set status='connected' where id=pg_temp.ident(5);
insert into public.ebay_connections(id,workspace_id,user_id,environment,status,external_account_id,authorization_version) values(pg_temp.ident(5,2),pg_temp.ident(3),pg_temp.ident(1,2),'sandbox','connected','sandbox-seller472',1);
insert into public.ebay_credentials(id,encrypted_tokens) values(pg_temp.ident(5,2),'sandbox-fixture');
create temporary table sandbox_claim as select public.ebay_order_observer_claim(true,'{}','{}','sandbox') as payload;
select is((select payload#>>'{connection,connection,environment}' from sandbox_claim),'sandbox','Sandboxkonfiguration beansprucht ausschliesslich Sandboxkonto');
select public.ebay_finish_read(pg_temp.ident(5,2),(select (payload#>>'{connection,connection,operation_id}')::uuid from sandbox_claim),1,null,false,false);
select is(public.ebay_order_observer_claim(true,'{}','{}','invalid'),null::jsonb,'Unbekannte Umgebung liest kein Konto');
create temporary table observer_claim as select public.ebay_order_observer_claim(true,'{}','{}') as payload;
select is((select payload#>>'{connection,connection,environment}' from observer_claim),'production','Productionkonfiguration ignoriert weiterhin faelliges altes Sandboxkonto');
delete from public.ebay_connections where id=pg_temp.ident(5,2);
select ok((select payload is not null from observer_claim),'Server beobachtet Konto ohne offenen Browser');
create function pg_temp.page(p_orders jsonb,p_complete boolean,p_offset integer default 0) returns boolean language sql as $$select public.ebay_order_observer_page(pg_temp.ident(5),(select (payload#>>'{connection,connection,operation_id}')::uuid from observer_claim),1,(select (payload#>>'{scan,from}')::timestamptz from observer_claim),(select (payload#>>'{scan,to}')::timestamptz from observer_claim),p_offset,p_orders,p_complete);$$;
select ok(pg_temp.page(jsonb_build_array(jsonb_build_object('id','baseline','createdAt',now()-interval '1 day')),true),'Erstbaseline vollstaendig gespeichert');
select is((select count(*) from public.web_push_events where connection_id=pg_temp.ident(5) and category='order'),0::bigint,'Erstbaseline erzeugt keinen eBay Meldungssturm');
select public.ebay_finish_read(pg_temp.ident(5),(select (payload#>>'{connection,connection,operation_id}')::uuid from observer_claim),1,null,false,true);
update public.ebay_order_observer_scans set next_due_at=now()-interval '1 second',watermark=now()-interval '5 minutes',baseline_to=now()-interval '10 minutes' where connection_id=pg_temp.ident(5);
update observer_claim set payload=public.ebay_order_observer_claim(true,'{}','{}');
select ok(pg_temp.page(jsonb_build_array(jsonb_build_object('id','new-order','createdAt',now()-interval '2 minutes')),false),'Neue Bestellung gespeichert auch vor Scanabschluss');
select is((select count(*) from public.web_push_events where connection_id=pg_temp.ident(5) and category='order'),1::bigint,'Neue Bestellung atomar einmal in Outbox');
select ok((select watermark<window_to from public.ebay_order_observer_scans where connection_id=pg_temp.ident(5)),'Teilscan schreibt Watermark nicht fort');
select ok(not pg_temp.page('[]',true,0),'Verspaetete Wiederholung einer Seite bleibt geschlossen');
select public.ebay_order_observer_delay(pg_temp.ident(5),(select (payload#>>'{connection,connection,operation_id}')::uuid from observer_claim),1,600);
select public.ebay_finish_read(pg_temp.ident(5),(select (payload#>>'{connection,connection,operation_id}')::uuid from observer_claim),1,null,false,true);
select is(public.ebay_order_observer_claim(true,'{}','{}'),null::jsonb,'Teilfehler respektiert Anbieterwartezeit');
update public.ebay_order_observer_scans set next_due_at=now()-interval '1 second' where connection_id=pg_temp.ident(5);
create temporary table frozen_window as select payload#>'{scan}' as scan from observer_claim;
update observer_claim set payload=public.ebay_order_observer_claim(true,'{}','{}');
select is((select payload#>>'{scan,to}' from observer_claim),(select scan->>'to' from frozen_window),'Fortsetzung behaelt gefrorenes Scanende');
select is((select payload#>>'{scan,offset}' from observer_claim),'50','Fortsetzung nutzt dauerhaften Cursor');
select ok(pg_temp.page(jsonb_build_array(jsonb_build_object('id','new-order','createdAt',now()-interval '2 minutes'),jsonb_build_object('id','historical','createdAt',now()-interval '12 minutes')),true,50),'Dedupe und historische Seite erfolgreich');
select is((select count(*) from public.web_push_events where connection_id=pg_temp.ident(5) and category='order'),1::bigint,'Wiederholung und historischer Backfill bleiben still');
select ok((select window_to is null and watermark is not null from public.ebay_order_observer_scans where connection_id=pg_temp.ident(5)),'Erst vollstaendiger Scan bestaetigt Watermark');
select is((select count(*) from public.ebay_order_bookings where workspace_id=pg_temp.ident(3)),0::bigint,'Beobachtung legt keine Buchhaltung an');
delete from public.workspace_members where user_id=pg_temp.ident(1,2);
select ok(not public.web_push_can_deliver(pg_temp.ident(1,2),pg_temp.ident(3),'order',pg_temp.ident(5),pg_temp.ident(2,2)),'Entzogene Mitgliedschaft wird vor Send geprueft');
update auth.sessions set not_after=now()-interval '1 second' where id=pg_temp.ident(2,1);
select ok(not public.web_push_can_deliver(pg_temp.ident(1,1),pg_temp.ident(3),'message',pg_temp.ident(4),pg_temp.ident(2,1)),'Widerrufene Sitzung wird vor Send geprueft');
select ok(not has_table_privilege('authenticated','public.ebay_order_observations','select'),'Dauerhafte Orderkennungen service-only');
select ok(not has_function_privilege('authenticated','public.ebay_order_observer_claim(boolean,uuid[],uuid[],text)','execute'),'Nutzer kann Beobachter nicht impersonieren');
insert into public.workspace_licenses(workspace_id,access_source,status,granted_days,starts_at,ends_at) values(pg_temp.ident(3),'beta','active',1,now()-interval '2 days',now()-interval '1 day');
select ok(not public.web_push_can_deliver(pg_temp.ident(1,3),pg_temp.ident(3),'order',null,pg_temp.ident(2,3)),'Abgelaufener Beta-Zugang verhindert auch Shopzustellung');
delete from public.workspace_licenses where workspace_id=pg_temp.ident(3);
update public.web_push_deliveries set status='expired',finished_at=clock_timestamp();
select public.web_push_enqueue_event('batch-test:'||number,pg_temp.ident(3),'test',null,'{"kind":"settings"}',pg_temp.ident(6,3)) from generate_series(1,10) number;
select is((select count(*) from public.web_push_claim('v1',true,'{}','{}')),4::bigint,'Nur vier sofort parallele Sends werden geleast; keine wartenden Claimwellen');
select * from finish();
rollback;
